mapper.select:
select
f.file_relation_id as fileRelationId,
mn.*
from  OA_Attendance_Leave mn
left join  Sys_File f on f.FileID=mn.Al_Id
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.Al_Type = #{params.alType}


    and mn.Al_State = #{params.alState}


    and mn.Al_Uname like concat('%',#{params.alUname},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Al_Create_Time desc
    

limit #{params.start},#{params.size}

select
count(1)
from  OA_Attendance_Leave mn
left join  Sys_File f on f.FileID=mn.Al_Id
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.Al_Type = #{params.alType}


    and mn.Al_State = #{params.alState}


    and mn.Al_Uname like concat('%',#{params.alUname},'%')
